-- Add new schema named "app"
CREATE SCHEMA "app";
-- Add new schema named "todo"
CREATE SCHEMA "todo";
-- Create extension "pg_trgm"
CREATE EXTENSION "pg_trgm" WITH SCHEMA "public" VERSION "1.6";
-- Create extension "ltree"
CREATE EXTENSION "ltree" WITH SCHEMA "public" VERSION "1.2";
-- Create "users" table
CREATE TABLE "app"."users" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "name" character varying NOT NULL,
  PRIMARY KEY ("id")
);
-- Create "moderators" table
CREATE TABLE "app"."moderators" (
  "user_id" bigint NOT NULL,
  "moderator_user_id" bigint NOT NULL,
  PRIMARY KEY ("user_id", "moderator_user_id"),
  CONSTRAINT "moderators_users_moderator" FOREIGN KEY ("moderator_user_id") REFERENCES "app"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "moderators_users_user" FOREIGN KEY ("user_id") REFERENCES "app"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "moderator_moderator_user_id" to table: "moderators"
CREATE INDEX "moderator_moderator_user_id" ON "app"."moderators" ("moderator_user_id");
-- Create index "moderator_user_id" to table: "moderators"
CREATE INDEX "moderator_user_id" ON "app"."moderators" ("user_id");
-- Create "reminders" table
CREATE TABLE "todo"."reminders" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 8589934592),
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
-- Set comment to table: "reminders"
COMMENT ON TABLE "todo"."reminders" IS 'Reminder for a user to take action.';
-- Create "todos" table
CREATE TABLE "todo"."todos" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 4294967296),
  "text" character varying NOT NULL,
  "done_at" timestamptz NULL,
  "owner_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "todos_users_todos" FOREIGN KEY ("owner_id") REFERENCES "app"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "todo_owner_id" to table: "todos"
CREATE INDEX "todo_owner_id" ON "todo"."todos" ("owner_id");
-- Create "todo_reminders" table
CREATE TABLE "todo"."todo_reminders" (
  "todo_id" bigint NOT NULL,
  "reminder_id" bigint NOT NULL,
  PRIMARY KEY ("todo_id", "reminder_id"),
  CONSTRAINT "todo_reminders_reminders_reminder" FOREIGN KEY ("reminder_id") REFERENCES "todo"."reminders" ("id") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "todo_reminders_todos_todo" FOREIGN KEY ("todo_id") REFERENCES "todo"."todos" ("id") ON UPDATE NO ACTION ON DELETE CASCADE
);
-- Set comment to table: "todo_reminders"
COMMENT ON TABLE "todo"."todo_reminders" IS 'A join table holding the relationships of todos to reminders';
